/**
 * The home's demos run on the owner's reel and its footage (#content/reels, generated by scripts/media.mjs): its
 * slots as segment-bar segments, its camera roll as cells of the frame atlas, and which clip each slot picks. Pure,
 * so test/unit/home-content.test.ts can hold it.
 */
import type { CSSProperties } from 'react';
import type { Segment } from '#components/ui/segments';
import { CAMERA_ROLL, DEFAULT_REEL_ID, REEL_WORDS, ROLL_FRAMES, reelById } from '#content/reels';
import type { Reel } from '#content/schema';

export const REEL: Reel = reelById(DEFAULT_REEL_ID);

/** The reel's slots as a segment bar's segments. */
export const REEL_SEGMENTS: readonly Segment[] = REEL.slots.map((s) => ({ start: s.start, end: s.end, group: s.role, unsure: s.uncertainCut }));

/** The reel's own title words ("Vietnam, walking away on every beat"). */
export const REEL_TITLE = REEL_WORDS[REEL.id]?.title ?? REEL.title;

/**
 * One cell of the frame atlas, cropped to any box: the cell is drawn at its own 9:16 inside an element that covers
 * the box (`cover` below), so a square thumb is the frame's middle, never a squashed frame.
 */
export function spriteStyle(sprite: number): CSSProperties {
  const { columns, rows, src } = CAMERA_ROLL.atlas;
  const index = Math.max(0, Math.min(sprite, columns * rows - 1));
  const x = columns > 1 ? ((index % columns) / (columns - 1)) * 100 : 0;
  const y = rows > 1 ? (Math.floor(index / columns) / (rows - 1)) * 100 : 0;
  return { backgroundImage: `url(${src})`, backgroundSize: `${columns * 100}% ${rows * 100}%`, backgroundPosition: `${x}% ${y}%`, backgroundRepeat: 'no-repeat' };
}

/** The atlas frame a clip shows as its thumbnail. */
export function clipSprite(clipId: string): number {
  return CAMERA_ROLL.clips.find((c) => c.id === clipId)?.sprite ?? 0;
}

/** A clip's length as the roll shows it, at least a second ("0:07"). */
export function clipDuration(clipId: string): string {
  const seconds = Math.max(1, Math.round(CAMERA_ROLL.clips.find((c) => c.id === clipId)?.durationSec ?? 1));
  return `0:${String(seconds).padStart(2, '0')}`;
}

export interface RollCell {
  readonly sprite: number;
  readonly clipId: string;
  /** This cell is the AI's pick for a slot (one per clip of the reel). */
  readonly picked: boolean;
}

/** A small, fixed shuffle (a linear congruential walk), so the server and the browser draw the same wall. */
function shuffled<T>(items: readonly T[], seed: number): T[] {
  const out = [...items];
  let s = seed;
  for (let i = out.length - 1; i > 0; i -= 1) {
    s = (s * 1103515245 + 12345) % 2147483648;
    const j = s % (i + 1);
    [out[i], out[j]] = [out[j]!, out[i]!];
  }
  return out;
}

/**
 * The camera roll wall: `count` cells drawn from every frame of the atlas. Each of the reel's clips appears once as
 * the pick for its slot; the rest of the wall is the roll's other frames (the other trips' clips too), so the picks
 * are scattered through it the way a real roll scatters them.
 */
export function rollWall(count: number, seed = 7): readonly RollCell[] {
  const clipIds = [...new Set(ROLL_FRAMES.map((f) => f.clipId))];
  const picked = new Set(REEL.slots.map((s) => s.pick.clipId));
  const picks = clipIds.filter((id) => picked.has(id)).map((clipId) => ({ sprite: clipSprite(clipId), clipId, picked: true }));
  const pickSprites = new Set(picks.map((p) => p.sprite));
  // The other frames, dealt round the clips in turn, so no one long shot fills the wall.
  const byClip = clipIds.map((clipId) => ROLL_FRAMES.filter((f) => f.clipId === clipId && !pickSprites.has(f.sprite)));
  const rest: RollCell[] = [];
  for (let round = 0; rest.length < ROLL_FRAMES.length - picks.length; round += 1) {
    for (const frames of byClip) {
      const f = frames[round];
      if (f) rest.push({ sprite: f.sprite, clipId: f.clipId, picked: false });
    }
  }
  const filler: RollCell[] = [];
  for (let i = 0; filler.length < Math.max(0, count - picks.length) && rest.length > 0; i += 1) filler.push(rest[i % rest.length]!);
  return shuffled([...picks, ...filler].slice(0, count), seed);
}

/** The reel's slots, each with the clip the AI picked for it, what the slot needs and the part it belongs to. */
export const SLOT_PICKS = REEL.slots.map((slot, i) => ({
  n: i + 1,
  role: slot.role,
  needs: slot.needs,
  clipId: slot.pick.clipId,
  sprite: clipSprite(slot.pick.clipId),
  seconds: Math.max(0, slot.end - slot.start),
}));

/** "0:06.5": a slot's length as the app's timecodes write it. */
export function shortTime(seconds: number): string {
  const whole = Math.floor(seconds);
  return `0:${String(whole).padStart(2, '0')}.${Math.round((seconds - whole) * 10) % 10}`;
}
